// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        value = bound(value, 0, 100 ether);
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;
        (bool sent, ) = address(c).call{value: value}("");
        require(sent, "initial eth transfer failed");
        contractBalanceBefore += value;
        vm.deal(address(c), contractBalanceBefore);

        // Now call go() — it should forward the entire contract balance to owner
        // but in the buggy version, it sends 0 to target and then sends all balance to owner
        // Actually the bug: target call uses value 0, so require may fail if target reverts, but if target accepts, then owner gets contract balance
        // The key: In reference, target receives msg.value, then owner gets remaining (which could be zero if msg.value equals contract balance). 
        // But the contract balance after call may differ. Simpler: after go(), owner gets all contract balance (which includes msg.value)
        // Actually reference: go() sends msg.value to target, then sends all contract balance to owner. If target call succeeds, owner gets contract balance = whatever was left.
        // But the bug: go() sends 0 to target, then sends all contract balance to owner. So owner always gets the full contract balance (including the sent value) regardless of msg.value.
        // The difference: In reference, owner receives contract balance after sending msg.value to target. In bug, owner receives full contract balance.
        // So property: after go(), owner balance increases by exactly the contract balance before go() (since go() sends all contract balance to owner).
        // But reference also sends msg.value to target, so contract balance decreases by msg.value before transfer to owner. So owner gets (contractBalanceBefore - msg.value).
        // Bug: target call uses 0, so contract balance unchanged, owner gets contractBalanceBefore.
        // So rule: ownerBalanceAfter - ownerBalanceBefore == (bug ? contractBalanceBefore : contractBalanceBefore - msg.value).
        // But we want a property that holds for reference and fails for bug. Let’s use: after go(), the balance of owner minus the balance of owner before equals the balance of the contract before go() minus the msg.value sent to go().
        // However, msg.value sent to go() is what we sent to c in the setup call. Let's capture that.
        uint256 ownerBalanceBeforeGo = owner.balance;
        c.go{value: value}();
        uint256 ownerBalanceAfterGo = owner.balance;
        // In reference: ownerBalanceAfterGo - ownerBalanceBeforeGo = contractBalanceBefore - value
        // In bug: ownerBalanceAfterGo - ownerBalanceBeforeGo = contractBalanceBefore
        // So: ownerBalanceAfterGo - ownerBalanceBeforeGo + value == contractBalanceBefore (reference) vs +value (bug) 
        // But contractBalanceBefore after adding our initial eth is not exactly known because of extra setup. Simpler: avoid extra eth transfer.
        // Let's directly: after go() with msg.value = value, the owner's balance increase should be equal to (address(this).balance before go() minus value) for reference.
        // But address(this).balance before go() is tricky due to miner tips? Let's use a clean approach: 
        // The property: The owner receives at most the contract's balance minus the value sent to target. But since we don't know target's behavior, we rely on that target call might fail. In reference, if target fails, require fails and transaction reverts.
        // In bug, target call always succeeds (sending 0), so require passes and owner gets all.
        // So a simpler property: The call to go() with msg.value = value reverts if the target call fails (i.e., if target has no payable fallback). But target 0xC8A60... is a random address, maybe no code? Actually target is a fixed address, likely has no code, so call will fail -> reference reverts, bug doesn't.
        // The difference: For any msg.value > 0, reference reverts because target call fails; bug passes. So property: go() should revert if msg.value > 0. But that's not general over fuzz because for msg.value == 0 both might pass? Let's test: for msg.value = 0, reference sends 0 to target, target call succeeds (even with no code, call{value:0} succeeds), so passes. Bug also passes. So property: go() does not revert iff msg.value == 0. That holds for reference, but for bug it never reverts. So rule: vm.expectRevert if value > 0; but we can't use expectRevert in fuzz because it will revert on bug. Instead, use try/catch.
        // Let's use: The function go() reverts if and only if msg.value != 0.
        // So assertTrue( (msg.value == 0 && !reverted) || (msg.value != 0 && reverted) ). But this is complex. Let's write:
        // We'll store whether go() reverted, then assert.
        bool reverted;
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSelector(c.go.selector));
        reverted = !success;
        // Reference: reverted = (value != 0) because target call fails; Bug: reverted = false always.
        // So property: reverted == (value != 0).
        assertTrue(reverted == (value != 0), "go() should revert iff non-zero value");
    }
}

