// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= 100 ether); // bound to avoid overflow in checks
        uint256 ownerInitial = payable(c.go()).balance;
        uint256 contractInitial = address(c).balance;
        vm.deal(address(c), contractInitial);
        vm.deal(address(this), amount);

        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
        require(success);

        // After go(), the owner's balance must have increased by at least amount (since the contract forwards msg.value to target, but target.balance may not accept? Actually target.call{value: msg.value} always succeeds if target is a contract that can receive ETH; for non-payable fallback it fails and require reverts. So we only consider valid cases where the call succeeds. In the reference, the contract sends msg.value to target, then sends all its remaining balance (which includes msg.value because it received msg.value) to owner. So owner gets at least msg.value.
        uint256 ownerFinal = payable(c.go()).balance;
        assertTrue(ownerFinal >= ownerInitial + amount - 1); // -1 for gas, but roughly
    }
}
